import { describe, expect, it } from 'vitest'
import {
  AROMATIC_ORDER_LABEL,
  AROMATIC_RING,
  BOND_KINDS,
  D_ORBITAL_NOTE,
  HYBRIDIZATION_HYDROGEN,
  HYBRIDIZATION_NOT_ASSIGNED,
  ORGANIC_OXYGEN_NOTE,
  RESONANCE_ATOM_NOTE,
  RESONANCE_ORDER_LABEL,
  RESONANCE_SIGMA_PI,
  RESONANCE_TRIPLE_ATOM_NOTE,
  RESONANCE_TRIPLE_ORDER_LABEL,
  RESONANCE_TRIPLE_SIGMA_PI,
  SIGMA_PI,
  TERMINAL_ATOM,
  deriveAtoms,
  deriveBonds,
} from './derive'
// The answer key: generated by `npm run build:expected` from the research
// table. It shares no code with derive.ts; the named cases below are the
// hand-written checks. See scripts/build-expected-fixture.mjs.
import expected from './expected-values.fixture.json'
import { registry } from './registry'
import type { Molecule } from './schema'

const { elements, molecules } = registry

function molecule(id: string): Molecule {
  const found = molecules.find((m) => m.id === id)
  if (!found) throw new Error(`no molecule ${id}`)
  return found
}

/** Stored and derived values of every atom, with its bonds, for picking atoms by description. */
function atomsOf(id: string) {
  const m = molecule(id)
  const derived = deriveAtoms(m, elements)
  return m.atoms.map((atom, i) => ({
    ...atom,
    ...derived[i]!,
    bonds: m.bonds
      .filter((b) => b.a === i || b.b === i)
      .map((b) => ({ order: b.order, to: m.atoms[b.a === i ? b.b : b.a]!.element })),
  }))
}

const only = <T>(items: T[]): T => {
  expect(items).toHaveLength(1)
  return items[0]!
}

// Compared as sorted lists of strings, so neither atom order nor key order matters.
const multiset = (tuples: (string | number | boolean)[][]) => tuples.map((t) => t.join(' | ')).sort()

describe('derived values against the expected-values table', () => {
  it('covers exactly the structures in the registry', () => {
    expect(expected.map((e) => e.id).sort()).toEqual(molecules.map((m) => m.id).sort())
  })

  describe.each(expected)('$id', (want) => {
    const m = molecule(want.id)

    it('has the expected charge', () => {
      expect(m.charge).toBe(want.charge)
    })

    it('stores the expected formal charge and lone pairs on every atom', () => {
      expect(multiset(m.atoms.map((a) => [a.element, a.formalCharge, a.lonePairs])), want.id).toEqual(
        multiset(want.atoms.map((a) => [a.element, a.formalCharge, a.lonePairs])),
      )
    })

    it('derives the expected oxidation state, geometry and hybridization for every atom', () => {
      const derived = deriveAtoms(m, elements)
      const got = m.atoms.map((a, i) => {
        const d = derived[i]!
        return [a.element, a.formalCharge, a.lonePairs, d.oxidationState, d.geometry, d.hybridization]
      })
      expect(multiset(got), want.id).toEqual(
        multiset(
          want.atoms.map((a) => [a.element, a.formalCharge, a.lonePairs, a.oxidationState, a.geometry, a.hybridization]),
        ),
      )
    })

    it('derives the expected order and sigma/pi composition for every bond', () => {
      const derived = deriveBonds(m, elements)
      // The table holds each bond as the Lewis structure draws it. A bond of a resonance pair displays
      // the shared π bond instead (tested below), so its drawn composition is read from its stored order.
      const got = m.bonds.map((b, i) => [
        [m.atoms[b.a]!.element, m.atoms[b.b]!.element].sort().join('-'),
        b.order,
        b.aromatic,
        b.resonanceNote ? SIGMA_PI[b.order] : derived[i]!.sigmaPi,
      ])
      expect(multiset(got), want.id).toEqual(
        multiset(want.bonds.map((b) => [b.elements.join('-'), b.order, b.aromatic, b.sigmaPi])),
      )
      // What deriveBonds says of a resonance-pair bond names the kind the table expects it drawn as.
      m.bonds.forEach((b, i) => {
        if (b.resonanceNote) expect(derived[i]!.orderNote, want.id).toContain(`as a ${BOND_KINDS[b.order - 1]} bond`)
      })
    })

    it('has oxidation states that sum to the charge', () => {
      const sum = deriveAtoms(m, elements).reduce((total, a) => total + a.oxidationState, 0)
      expect(sum).toBe(m.charge)
    })
  })
})

describe('named cases (spec 6.5)', () => {
  it('H2O2: each oxygen is -1', () => {
    const oxygens = atomsOf('hydrogen-peroxide').filter((a) => a.element === 'O')
    expect(oxygens.map((a) => a.oxidationState)).toEqual([-1, -1])
  })

  it('acetamide: N is sp² and trigonal planar', () => {
    const n = only(atomsOf('acetamide').filter((a) => a.element === 'N'))
    expect(n).toMatchObject({ resonanceOverride: true, hybridization: 'sp²', geometry: 'trigonal planar' })
  })

  it('urea: both N are sp² and trigonal planar', () => {
    const nitrogens = atomsOf('urea').filter((a) => a.element === 'N')
    expect(nitrogens).toHaveLength(2)
    for (const n of nitrogens) {
      expect(n).toMatchObject({ resonanceOverride: true, hybridization: 'sp²', geometry: 'trigonal planar' })
    }
  })

  it('methylamine: an amine N with no neighbouring double bond stays sp³ and trigonal pyramidal', () => {
    const n = only(atomsOf('methylamine').filter((a) => a.element === 'N'))
    expect(n).toMatchObject({ resonanceOverride: false, hybridization: 'sp³', geometry: 'trigonal pyramidal' })
  })

  it('acetic acid: the O-H oxygen is sp³ and bent, with the organic-chemistry note', () => {
    const oh = only(atomsOf('acetic-acid').filter((a) => a.element === 'O' && a.bondedAtoms === 2))
    expect(oh).toMatchObject({
      resonanceOverride: false,
      hybridization: 'sp³',
      geometry: 'bent',
      electronGeometry: 'tetrahedral',
      hybridizationNote: ORGANIC_OXYGEN_NOTE,
    })
  })

  it('ethyl acetate: the ester oxygen is sp³ and bent, with the organic-chemistry note', () => {
    const ester = only(atomsOf('ethyl-acetate').filter((a) => a.element === 'O' && a.bondedAtoms === 2))
    expect(ester).toMatchObject({ hybridization: 'sp³', geometry: 'bent', hybridizationNote: ORGANIC_OXYGEN_NOTE })
  })

  it('ethanol and water: an oxygen with no neighbouring C=O carries no note', () => {
    for (const id of ['ethanol', 'water']) {
      const o = only(atomsOf(id).filter((a) => a.element === 'O'))
      expect(o).toMatchObject({ hybridization: 'sp³', geometry: 'bent' })
      expect(o.hybridizationNote).toBeUndefined()
    }
  })

  it('SF6: a terminal halogen is "not assigned (terminal atom)" with geometry "terminal atom"', () => {
    const fluorines = atomsOf('sulfur-hexafluoride').filter((a) => a.element === 'F')
    expect(fluorines).toHaveLength(6)
    for (const f of fluorines) {
      expect(f).toMatchObject({
        hybridization: HYBRIDIZATION_NOT_ASSIGNED,
        geometry: TERMINAL_ATOM,
        electronGeometry: null,
        oxidationState: -1,
      })
    }
  })

  it('bicarbonate: the singly bonded O- is "not assigned (terminal atom)"', () => {
    const o = only(atomsOf('bicarbonate').filter((a) => a.formalCharge === -1))
    expect(o).toMatchObject({ element: 'O', hybridization: HYBRIDIZATION_NOT_ASSIGNED, geometry: TERMINAL_ATOM })
  })

  it('SO2: S is +4, bent, sp², formal charge +1', () => {
    const s = only(atomsOf('sulfur-dioxide').filter((a) => a.element === 'S'))
    expect(s).toMatchObject({ oxidationState: 4, geometry: 'bent', hybridization: 'sp²', formalCharge: 1, lonePairs: 1 })
  })

  it.each(['sulfur-dioxide', 'glycine-zwitterion', 'alanine-zwitterion', 'bicarbonate'])(
    '%s: the two oxygens of the resonance pair display differently and both carry the resonance note',
    (id) => {
      const pair = atomsOf(id).filter((a) => a.element === 'O' && a.bondedAtoms === 1)
      expect(pair.map((a) => a.hybridization).sort()).toEqual([HYBRIDIZATION_NOT_ASSIGNED, 'sp²'])
      expect(pair.map((a) => a.hybridizationNote)).toEqual([RESONANCE_ATOM_NOTE, RESONANCE_ATOM_NOTE])
    },
  )

  it('acetone and SF6: a terminal atom outside a resonance pair carries no note', () => {
    for (const id of ['acetone', 'sulfur-hexafluoride']) {
      const terminal = atomsOf(id).filter((a) => a.bondedAtoms === 1 && a.element !== 'H')
      expect(terminal.map((a) => a.hybridizationNote)).toEqual(terminal.map(() => undefined))
    }
  })

  it('SF6: S is octahedral, with the d-orbital note', () => {
    const s = only(atomsOf('sulfur-hexafluoride').filter((a) => a.element === 'S'))
    expect(s).toMatchObject({
      geometry: 'octahedral',
      hybridization: 'sp³d² (textbook label)',
      hybridizationNote: D_ORBITAL_NOTE,
      oxidationState: 6,
    })
  })

  it('XeF4: Xe is square planar with two lone pairs', () => {
    const xe = only(atomsOf('xenon-tetrafluoride').filter((a) => a.element === 'Xe'))
    expect(xe).toMatchObject({
      geometry: 'square planar',
      electronGeometry: 'octahedral',
      lonePairs: 2,
      hybridization: 'sp³d² (textbook label)',
    })
  })

  it('PCl5: P is trigonal bipyramidal', () => {
    const p = only(atomsOf('phosphorus-pentachloride').filter((a) => a.element === 'P'))
    expect(p).toMatchObject({
      geometry: 'trigonal bipyramidal',
      hybridization: 'sp³d (textbook label)',
      hybridizationNote: D_ORBITAL_NOTE,
    })
  })

  it('benzene: all six ring bonds are aromatic and display order 1.5', () => {
    const m = molecule('benzene')
    const derived = deriveBonds(m, elements)
    const ring = m.bonds.flatMap((b, i) =>
      m.atoms[b.a]!.element === 'C' && m.atoms[b.b]!.element === 'C' ? [{ ...b, ...derived[i]! }] : [],
    )
    expect(ring).toHaveLength(6)
    for (const bond of ring) {
      expect(bond).toMatchObject({ aromatic: true, displayOrder: 1.5, orderLabel: AROMATIC_ORDER_LABEL })
    }
  })

  it('hydrogen is "none (1s)"', () => {
    const hydrogens = atomsOf('methane').filter((a) => a.element === 'H')
    expect(hydrogens.map((h) => h.hybridization)).toEqual(Array(4).fill(HYBRIDIZATION_HYDROGEN))
  })

  it('acetone: the carbonyl O is sp²', () => {
    const o = only(atomsOf('acetone').filter((a) => a.element === 'O'))
    expect(o).toMatchObject({ hybridization: 'sp²', geometry: TERMINAL_ATOM })
  })

  it('N2: N is sp', () => {
    expect(atomsOf('nitrogen').map((a) => a.hybridization)).toEqual(['sp', 'sp'])
  })

  it('O2 and CO2: O is sp²', () => {
    for (const id of ['oxygen', 'carbon-dioxide']) {
      const oxygens = atomsOf(id).filter((a) => a.element === 'O')
      expect(oxygens.map((a) => a.hybridization)).toEqual(['sp²', 'sp²'])
    }
  })
})

describe('deriveBonds', () => {
  it('gives a non-aromatic bond its stored order and no label', () => {
    const m = molecule('carbon-dioxide')
    for (const bond of deriveBonds(m, elements)) {
      expect(bond).toMatchObject({ displayOrder: 2, sigmaPi: '1 σ + 1 π', electronegativityDifference: 0.89 })
      expect(bond.orderLabel).toBeUndefined()
    }
  })

  it.each(['sulfur-dioxide', 'glycine-zwitterion', 'alanine-zwitterion', 'bicarbonate'])(
    '%s: both bonds of the resonance pair display order 1.5 and a shared π bond, and say how each is drawn',
    (id) => {
      const m = molecule(id)
      const derived = deriveBonds(m, elements)
      const pair = m.bonds.flatMap((b, i) => (b.resonanceNote ? [{ ...b, ...derived[i]! }] : []))
      expect(pair.map((b) => b.order).sort()).toEqual([1, 2])
      for (const bond of pair) {
        expect(bond).toMatchObject({ displayOrder: 1.5, orderLabel: RESONANCE_ORDER_LABEL, sigmaPi: RESONANCE_SIGMA_PI })
        expect(bond.orderNote).toBe(
          `The Lewis structure draws this bond as a ${bond.order === 2 ? 'double' : 'single'} bond, in one of two equivalent resonance structures; the two real bonds are equal.`,
        )
      }
      // Every other bond keeps its stored order and has no note.
      m.bonds.forEach((b, i) => {
        if (!b.resonanceNote) expect(derived[i]).toMatchObject({ displayOrder: b.order, sigmaPi: SIGMA_PI[b.order] })
        if (!b.resonanceNote) expect(derived[i]!.orderNote).toBeUndefined()
      })
    },
  )

  it('measures length from the stored coordinates', () => {
    const lengths = deriveBonds(molecule('water'), elements).map((b) => b.length)
    expect(lengths[0]).toBeCloseTo(0.958, 3)
    expect(lengths[1]).toBeCloseTo(0.958, 3)
  })
})

describe('deriveAtoms on structures outside the library', () => {
  const atom = (element: string, lonePairs: number) => ({
    element,
    position: [0, 0, 0] as [number, number, number],
    position2d: [0, 0] as [number, number],
    formalCharge: 0,
    lonePairs,
  })
  const star = (centre: ReturnType<typeof atom>, ligands: number): Molecule => ({
    ...molecule('water'),
    id: 'test',
    atoms: [centre, ...Array.from({ length: ligands }, () => atom('F', 3))],
    bonds: Array.from({ length: ligands }, (_, i) => ({ a: 0, b: i + 1, order: 1 as const, aromatic: false })),
    measurements: undefined,
  })

  it.each([
    ['seesaw', 'S', 1, 4],
    ['T-shaped', 'Cl', 2, 3],
    ['linear', 'Xe', 3, 2],
    ['square pyramidal', 'Cl', 1, 5],
  ])('looks up %s', (geometry, element, lonePairs, ligands) => {
    expect(deriveAtoms(star(atom(element, lonePairs), ligands), elements)[0]!.geometry).toBe(geometry)
  })

  it('throws on a steric number and lone-pair combination it does not know', () => {
    expect(() => deriveAtoms(star(atom('Xe', 0), 7), elements)).toThrow(/test: atom 0 \(Xe\) has no entry for 7/)
  })
})

describe('named cases, the molecules added on 2026-10-09', () => {
  it('ozone: every oxygen is 0, as in any element; the central one is +1 in formal charge, bent and sp²', () => {
    const atoms = atomsOf('ozone')
    expect(atoms.map((a) => a.oxidationState)).toEqual([0, 0, 0])
    expect(only(atoms.filter((a) => a.bondedAtoms === 2))).toMatchObject({ formalCharge: 1, lonePairs: 1, geometry: 'bent', hybridization: 'sp²' })
    expect(atoms.filter((a) => a.bondedAtoms === 1).map((a) => a.formalCharge).sort()).toEqual([-1, 0])
  })

  it('hydrogen and chlorine: each atom is 0', () => {
    for (const id of ['hydrogen', 'chlorine']) expect(atomsOf(id).map((a) => a.oxidationState), id).toEqual([0, 0])
  })

  it('an ion of one element is not an elemental substance: the rule for like atoms still holds', () => {
    const oxygen = molecule('oxygen')
    const peroxide: Molecule = {
      ...oxygen,
      id: 'test',
      charge: -2,
      atoms: oxygen.atoms.map((a) => ({ ...a, formalCharge: -1, lonePairs: 3 })),
      bonds: oxygen.bonds.map((b) => ({ ...b, order: 1 as const })),
    }
    expect(deriveAtoms(peroxide, elements).map((a) => a.oxidationState)).toEqual([-1, -1])
  })

  it('carbon monoxide: C is -1 and O +1 in formal charge, +2 and -2 in oxidation state, and both are sp', () => {
    const atoms = atomsOf('carbon-monoxide')
    expect(only(atoms.filter((a) => a.element === 'C'))).toMatchObject({ formalCharge: -1, lonePairs: 1, oxidationState: 2, hybridization: 'sp' })
    expect(only(atoms.filter((a) => a.element === 'O'))).toMatchObject({ formalCharge: 1, lonePairs: 1, oxidationState: -2, hybridization: 'sp' })
  })

  it('hydrogen cyanide: C is +2, linear and sp; N is -3 and sp', () => {
    const atoms = atomsOf('hydrogen-cyanide')
    expect(only(atoms.filter((a) => a.element === 'C'))).toMatchObject({ oxidationState: 2, geometry: 'linear', hybridization: 'sp' })
    expect(only(atoms.filter((a) => a.element === 'N'))).toMatchObject({ oxidationState: -3, geometry: TERMINAL_ATOM, hybridization: 'sp' })
  })

  it.each([
    ['nitrate', 'N', 5, 1],
    ['carbonate', 'C', 4, 0],
    ['sulfur-trioxide', 'S', 6, 2],
  ])('%s: %s is trigonal planar and sp², and its three bonds are a resonance set of three with order 4/3', (id, element, oxidationState, formalCharge) => {
    const centre = only(atomsOf(id).filter((a) => a.element === element))
    expect(centre).toMatchObject({ oxidationState, formalCharge, lonePairs: 0, geometry: 'trigonal planar', hybridization: 'sp²' })
    const m = molecule(id)
    const derived = deriveBonds(m, elements)
    expect(m.bonds.map((b) => b.order).sort()).toEqual([1, 1, 2])
    m.bonds.forEach((bond, i) => {
      expect(derived[i]).toMatchObject({ orderLabel: RESONANCE_TRIPLE_ORDER_LABEL, sigmaPi: RESONANCE_TRIPLE_SIGMA_PI })
      expect(derived[i]!.displayOrder).toBeCloseTo(4 / 3, 10)
      expect(derived[i]!.orderNote).toBe(
        `The Lewis structure draws this bond as a ${bond.order === 2 ? 'double' : 'single'} bond, in one of three equivalent resonance structures; the three real bonds are equal.`,
      )
    })
    // The three oxygens read differently as drawn (one sp², two "not assigned") and each says they are the same atom.
    for (const oxygen of atomsOf(id).filter((a) => a.element === 'O')) expect(oxygen.hybridizationNote).toBe(RESONANCE_TRIPLE_ATOM_NOTE)
  })

  it.each([
    ['sulfate', 'S', 6, 2, 4],
    ['phosphate', 'P', 5, 1, 4],
    ['sulfuric-acid', 'S', 6, 2, 2],
    ['phosphoric-acid', 'P', 5, 1, 1],
  ])('%s in the octet form: %s is tetrahedral and sp³ with only single bonds, and no bond is a resonance bond', (id, element, oxidationState, formalCharge, negativeOxygens) => {
    const atoms = atomsOf(id)
    const centre = only(atoms.filter((a) => a.element === element))
    expect(centre).toMatchObject({ oxidationState, formalCharge, lonePairs: 0, geometry: 'tetrahedral', hybridization: 'sp³' })
    expect(centre.bonds.map((b) => b.order)).toEqual([1, 1, 1, 1])
    const charged = atoms.filter((a) => a.element === 'O' && a.formalCharge === -1)
    expect(charged).toHaveLength(negativeOxygens)
    for (const oxygen of charged) expect(oxygen).toMatchObject({ lonePairs: 3, oxidationState: -2, hybridization: HYBRIDIZATION_NOT_ASSIGNED })
    expect(molecule(id).bonds.some((b) => b.resonanceNote)).toBe(false)
  })

  it.each([
    ['sulfur-tetrafluoride', 'S', 4, 1, 'seesaw'],
    ['chlorine-trifluoride', 'Cl', 3, 2, 'T-shaped'],
    ['xenon-difluoride', 'Xe', 2, 3, 'linear'],
  ])('%s: %s has oxidation state +%i, %i lone pairs and is %s, with the d-orbital note', (id, element, oxidationState, lonePairs, geometry) => {
    const centre = only(atomsOf(id).filter((a) => a.element === element && a.bondedAtoms > 1))
    expect(centre).toMatchObject({
      oxidationState,
      lonePairs,
      geometry,
      electronGeometry: 'trigonal bipyramidal',
      hybridization: 'sp³d (textbook label)',
      hybridizationNote: D_ORBITAL_NOTE,
    })
  })

  it('phosphorus trichloride is trigonal pyramidal; the three chlorinated methanes are tetrahedral with C at +4, +2 and 0', () => {
    expect(only(atomsOf('phosphorus-trichloride').filter((a) => a.element === 'P'))).toMatchObject({
      oxidationState: 3,
      lonePairs: 1,
      geometry: 'trigonal pyramidal',
      hybridization: 'sp³',
    })
    const carbon = (id: string) => only(atomsOf(id).filter((a) => a.element === 'C'))
    expect(['carbon-tetrachloride', 'chloroform', 'dichloromethane'].map((id) => [carbon(id).oxidationState, carbon(id).geometry])).toEqual([
      [4, 'tetrahedral'],
      [2, 'tetrahedral'],
      [0, 'tetrahedral'],
    ])
  })

  it('phenol: the O-H oxygen is sp³ and bent, and its note names the aromatic ring, not a C=O', () => {
    const oxygen = only(atomsOf('phenol').filter((a) => a.element === 'O'))
    expect(oxygen).toMatchObject({ geometry: 'bent', hybridization: 'sp³', resonanceOverride: false, delocalisedInto: AROMATIC_RING })
    expect(oxygen.hybridizationNote).toBe('organic chemistry describes this oxygen as sp², because one lone pair is delocalised into the neighbouring aromatic ring')
  })

  it('aspirin: the ester oxygen between the ring and a C=O names the C=O', () => {
    const ester = only(atomsOf('aspirin').filter((a) => a.element === 'O' && a.bondedAtoms === 2 && a.bonds.every((b) => b.to === 'C')))
    expect(ester.hybridizationNote).toBe(ORGANIC_OXYGEN_NOTE)
  })

  it('nitric acid: the O-H oxygen is sp³ and bent and carries no organic-chemistry note; N is +5', () => {
    const atoms = atomsOf('nitric-acid')
    const hydroxyl = only(atoms.filter((a) => a.element === 'O' && a.bondedAtoms === 2))
    expect(hydroxyl).toMatchObject({ geometry: 'bent', hybridization: 'sp³' })
    expect(hydroxyl.hybridizationNote).toBeUndefined()
    expect(only(atoms.filter((a) => a.element === 'N'))).toMatchObject({ oxidationState: 5, formalCharge: 1, geometry: 'trigonal planar' })
  })

  it('serotonin: the ring N-H is sp² and trigonal planar, its lone pair shared with the ring; the amine N is sp³', () => {
    const nitrogens = atomsOf('serotonin').filter((a) => a.element === 'N')
    const ring = only(nitrogens.filter((a) => a.bonds.filter((b) => b.to === 'C').length === 2))
    expect(ring).toMatchObject({ resonanceOverride: true, geometry: 'trigonal planar', hybridization: 'sp²' })
    expect(['C=C', AROMATIC_RING]).toContain(ring.delocalisedInto)
    expect(only(nitrogens.filter((a) => a !== ring))).toMatchObject({ resonanceOverride: false, geometry: 'trigonal pyramidal', hybridization: 'sp³' })
  })

  it('nicotine: the ring nitrogen with a double bond is sp² and bent, the other sp³ and trigonal pyramidal', () => {
    const nitrogens = atomsOf('nicotine').filter((a) => a.element === 'N')
    expect(only(nitrogens.filter((a) => a.bondedAtoms === 2))).toMatchObject({ geometry: 'bent', hybridization: 'sp²', lonePairs: 1 })
    expect(only(nitrogens.filter((a) => a.bondedAtoms === 3))).toMatchObject({ geometry: 'trigonal pyramidal', hybridization: 'sp³' })
  })

  it('toluene: the six ring bonds are aromatic and the bond to the methyl carbon is an ordinary single bond', () => {
    const m = molecule('toluene')
    const derived = deriveBonds(m, elements)
    const carbonCarbon = m.bonds.flatMap((b, i) => (m.atoms[b.a]!.element === 'C' && m.atoms[b.b]!.element === 'C' ? [{ ...b, ...derived[i]! }] : []))
    expect(carbonCarbon.filter((b) => b.aromatic)).toHaveLength(6)
    expect(only(carbonCarbon.filter((b) => !b.aromatic))).toMatchObject({ order: 1, displayOrder: 1, sigmaPi: '1 σ' })
  })

  it('indigo has two benzene rings; no bond to an atom other than carbon is flagged aromatic anywhere in the library', () => {
    expect(molecule('indigo').bonds.filter((b) => b.aromatic)).toHaveLength(12)
    for (const m of molecules) {
      for (const b of m.bonds) if (b.aromatic) expect([m.id, m.atoms[b.a]!.element, m.atoms[b.b]!.element]).toEqual([m.id, 'C', 'C'])
    }
  })

  it('cysteine: S is -2, bent and sp³', () => {
    expect(only(atomsOf('cysteine').filter((a) => a.element === 'S'))).toMatchObject({ oxidationState: -2, geometry: 'bent', hybridization: 'sp³' })
  })

  it.each(['ozone', 'nitric-acid', 'acetate', 'serine-zwitterion', 'cysteine-zwitterion'])('%s: two bonds are a resonance pair, one drawn double', (id) => {
    const m = molecule(id)
    const derived = deriveBonds(m, elements)
    const pair = m.bonds.flatMap((b, i) => (b.resonanceNote ? [{ ...b, ...derived[i]! }] : []))
    expect(pair.map((b) => b.order).sort()).toEqual([1, 2])
    for (const bond of pair) expect(bond).toMatchObject({ displayOrder: 1.5, orderLabel: RESONANCE_ORDER_LABEL, sigmaPi: RESONANCE_SIGMA_PI })
  })
})
